package org.apache.commons.math.optimization;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.random.JDKRandomGenerator;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.LocalizedFormats;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class MultiStartUnivariateRealOptimizer_getResult_TriageGen1Test {

    private UnivariateRealOptimizer mockOptimizer;
    private RandomGenerator mockGenerator;
    private MultiStartUnivariateRealOptimizer optimizer;

    @Before
    public void setUp() {
        mockOptimizer = mock(UnivariateRealOptimizer.class);
        mockGenerator = new JDKRandomGenerator();
        // The constructor uses the provided optimizer internally to delegate calls
        optimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 1, mockGenerator);
    }

    @Test
    public void testGetResult_ReturnsValueFromOptimizer() throws ConvergenceException, FunctionEvaluationException {
        // Arrange
        double expectedResult = 42.0;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        // Act
        double actualResult = optimizer.getResult();

        // Assert
        assertEquals("getResult should return the value provided by the underlying optimizer", expectedResult, actualResult, 1e-15);
    }

    @Test
    public void testGetResult_WithNegativeValue() throws ConvergenceException, FunctionEvaluationException {
        // Arrange
        double expectedResult = -10.5;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        // Act
        double actualResult = optimizer.getResult();

        // Assert
        assertEquals("getResult should handle negative values correctly", expectedResult, actualResult, 1e-15);
    }

    @Test
    public void testGetResult_WithZero() throws ConvergenceException, FunctionEvaluationException {
        // Arrange
        double expectedResult = 0.0;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        // Act
        double actualResult = optimizer.getResult();

        // Assert
        assertEquals("getResult should handle zero correctly", expectedResult, actualResult, 1e-15);
    }

    @Test
    public void testGetResult_WithNaN() throws ConvergenceException, FunctionEvaluationException {
        // Arrange
        double expectedResult = Double.NaN;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        // Act
        double actualResult = optimizer.getResult();

        // Assert
        assertEquals("getResult should return NaN if the underlying optimizer returns NaN", expectedResult, actualResult, 0.0);
    }

    @Test
    public void testGetResult_WithInfinity() throws ConvergenceException, FunctionEvaluationException {
        // Arrange
        double expectedResult = Double.POSITIVE_INFINITY;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        // Act
        double actualResult = optimizer.getResult();

        // Assert
        assertEquals("getResult should handle positive infinity", expectedResult, actualResult, 0.0);
    }
}
